{"language":"Vyper","sources":{"src/TallyB.vy":{"content":"# pragma version 0.4.3
# explorer-verify live probe 2026-11-19: Vyper on Etherscan v2

owner: public(immutable(address))
label: public(String[32])
total: public(uint256)


@deploy
def __init__(start: uint256, label_: String[32]):
    owner = msg.sender
    self.total = start + 1
    self.label = label_


@external
def add(amount: uint256) -> uint256:
    self.total += amount
    return self.total
